  /* ===== giencoder Select / DatePicker 交互绑定（注入 DOM 后执行） ===== */
  function bindComponents(root) {
    function $(s, r) { return (r || document).querySelector(s); }
    function $$(s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); }
    function pad2(n) { return (n < 10 ? '0' : '') + n; }

    /* ---- Select：展开/收起、选项互斥、清除、外部点击收起 ---- */
    $$('.giencoder-select', root).forEach(function (sel) {
      if (sel.classList.contains('giencoder-select-disabled') || sel._bound) return;
      sel._bound = true;
      var view = $('.giencoder-select-view', sel);
      var popup = $('.giencoder-select-popup', sel);
      if (!view || !popup) return;
      var options = $$('.giencoder-select-option', popup);
      var textEl = $('.giencoder-select-view-text', view);
      var clearBtn = $('.giencoder-select-clear', sel);
      var placeholder = textEl ? (textEl.getAttribute('data-placeholder') || '') : '';

      function open() {
        popup.style.display = '';
        requestAnimationFrame(function () { if (popup.isConnected) popup.classList.add('giencoder-popup-open'); });
        view.setAttribute('aria-expanded', 'true');
      }
      function close() {
        popup.classList.remove('giencoder-popup-open');
        setTimeout(function () {
          if (popup.isConnected && !popup.classList.contains('giencoder-popup-open')) popup.style.display = 'none';
        }, 200);
        view.setAttribute('aria-expanded', 'false');
      }
      function isOpen() { return popup.classList.contains('giencoder-popup-open'); }

      view.addEventListener('click', function (ev) { ev.stopPropagation(); isOpen() ? close() : open(); });
      view.addEventListener('keydown', function (ev) {
        if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); isOpen() ? close() : open(); }
        if (ev.key === 'Escape') close();
      });
      options.forEach(function (opt) {
        opt.addEventListener('click', function (ev) {
          ev.stopPropagation();
          if (opt.classList.contains('giencoder-select-option-disabled')) return;
          options.forEach(function (o) { o.classList.remove('giencoder-select-option-selected'); o.setAttribute('aria-selected', 'false'); });
          opt.classList.add('giencoder-select-option-selected');
          opt.setAttribute('aria-selected', 'true');
          if (textEl) textEl.textContent = opt.textContent;
          sel.classList.add('giencoder-select-has-value');
          close();
        });
      });
      if (clearBtn) {
        clearBtn.addEventListener('click', function (ev) {
          ev.stopPropagation();
          options.forEach(function (o) { o.classList.remove('giencoder-select-option-selected'); o.setAttribute('aria-selected', 'false'); });
          if (textEl) textEl.textContent = placeholder;
          sel.classList.remove('giencoder-select-has-value');
          close();
        });
      }
    });

    /* ---- DatePicker(range)：展开/收起、范围两击选择、月份导航、外部收起 ---- */
    $$('.giencoder-date-picker', root).forEach(function (picker) {
      if (picker._bound) return;
      picker._bound = true;
      var trigger = $('.giencoder-input-wrapper', picker);
      var popup = $('.giencoder-date-picker-popup', picker);
      var input = trigger ? $('.giencoder-input', trigger) : null;
      if (!trigger || !popup || !input) return;

      var isRange = picker.getAttribute('data-variant') === 'range';
      var range = { start: null, end: null };

      function setOpen(open) {
        trigger.setAttribute('aria-expanded', open ? 'true' : 'false');
        if (open) {
          popup.style.display = 'block';
          requestAnimationFrame(function () { if (popup.isConnected) popup.classList.add('giencoder-panel-open'); });
        } else {
          popup.classList.remove('giencoder-panel-open');
          setTimeout(function () {
            if (popup.isConnected && !popup.classList.contains('giencoder-panel-open')) popup.style.display = 'none';
          }, 200);
        }
      }
      trigger.addEventListener('click', function (ev) {
        ev.stopPropagation();
        setOpen(!popup.classList.contains('giencoder-panel-open'));
      });
      trigger.addEventListener('keydown', function (ev) {
        if (ev.key === 'Escape') setOpen(false);
      });

      /* 月份导航：标题加减一月，range 变体第二面板联动 +1 月 */
      $$('.giencoder-calendar-nav', picker).forEach(function (nav) {
        nav.addEventListener('click', function (ev) {
          ev.stopPropagation();
          var back = nav.getAttribute('aria-label') === '上个月';
          var delta = back ? -1 : 1;
          var cals = $$('.giencoder-calendar', picker);
          cals.forEach(function (cal, idx) {
            var title = $('.giencoder-calendar-title', cal);
            if (!title) return;
            var m = title.textContent.match(/(\d{4})年(\d{1,2})月/);
            if (!m) return;
            var y = +m[1], mo = +m[2] + delta * (isRange && idx === 1 ? 1 : 1);
            if (isRange) { /* 双面板保持相差一个月：统一按左面板推进 */ }
            if (mo < 1) { mo = 12; y -= 1; }
            if (mo > 12) { mo = 1; y += 1; }
            title.textContent = y + '年' + mo + '月';
          });
          if (isRange && cals.length > 1) {
            /* 右面板 = 左面板 + 1 月 */
            var lt = $('.giencoder-calendar-title', cals[0]).textContent.match(/(\d{4})年(\d{1,2})月/);
            var y = +lt[1], mo = +lt[2] + 1;
            if (mo > 12) { mo = 1; y += 1; }
            $('.giencoder-calendar-title', cals[1]).textContent = y + '年' + mo + '月';
          }
        });
      });

      /* 日期格点击：range 两击起止 / single 互斥选中；跨月与空格忽略 */
      $$('.giencoder-calendar-cell', picker).forEach(function (cell) {
        if (cell.classList.contains('giencoder-calendar-cell-empty')) return;
        cell.addEventListener('click', function (ev) {
          ev.stopPropagation();
          if (cell.classList.contains('giencoder-calendar-cell-other')) return;
          var day = parseInt(cell.textContent, 10);
          if (isNaN(day)) return;
          var cal = cell.closest('.giencoder-calendar');
          var title = cal ? $('.giencoder-calendar-title', cal) : null;
          var m = title ? title.textContent.match(/(\d{4})年(\d{1,2})月/) : null;
          var date = (m ? +m[1] : 2026) + '/' + pad2(m ? +m[2] : 8) + '/' + pad2(day);

          if (isRange) {
            if (!range.start || (range.start && range.end)) { range.start = date; range.end = null; }
            else { range.end = date; }
            input.value = range.end ? range.start + ' - ' + range.end : range.start;
            if (range.start && range.end) setOpen(false);
            return;
          }
          $$('.giencoder-calendar-cell', picker).forEach(function (c) { c.classList.remove('giencoder-calendar-cell-selected'); });
          cell.classList.add('giencoder-calendar-cell-selected');
          input.value = date;
          setOpen(false);
        });
      });
    });
  }
  document.addEventListener('click', function (ev) {
    /* 外部点击收起全部弹层 */
    document.querySelectorAll('.giencoder-select').forEach(function (sel) {
      var popup = sel.querySelector('.giencoder-select-popup');
      if (popup && !sel.contains(ev.target)) {
        popup.classList.remove('giencoder-popup-open');
        setTimeout(function () { if (!popup.classList.contains('giencoder-popup-open')) popup.style.display = 'none'; }, 200);
        var v = sel.querySelector('.giencoder-select-view');
        if (v) v.setAttribute('aria-expanded', 'false');
      }
    });
    document.querySelectorAll('.giencoder-date-picker').forEach(function (pk) {
      var popup = pk.querySelector('.giencoder-date-picker-popup');
      var trigger = pk.querySelector('.giencoder-input-wrapper');
      if (popup && trigger && !pk.contains(ev.target)) {
        popup.classList.remove('giencoder-panel-open');
        setTimeout(function () { if (!popup.classList.contains('giencoder-panel-open')) popup.style.display = 'none'; }, 200);
        trigger.setAttribute('aria-expanded', 'false');
      }
    });
  });


  /* ===== 需求看板：radio 切换 / 分页 / 加载状态机 ===== */
  function bindReqPage(wrap) {
    wrap.addEventListener('click', function (ev) {
      var tab = ev.target.closest ? ev.target.closest('.kb-radio-btn[data-goto]') : null;
      if (tab && !tab.classList.contains('is-on')) {
        var g = tab.getAttribute('data-goto');
        if (g) { location.href = g; return; }
      }
      var pgItem = ev.target.closest ? ev.target.closest('.giencoder-pagination-item') : null;
      if (pgItem && !pgItem.classList.contains('giencoder-pagination-item-ellipsis')) {
        var pg = wrap.querySelector('.giencoder-pagination');
        if (pg) {
          var nums = Array.prototype.filter.call(pg.querySelectorAll('.giencoder-pagination-item'), function (n) {
            return !n.hasAttribute('aria-label') && !n.classList.contains('giencoder-pagination-item-ellipsis');
          });
          var max = nums.length ? parseInt(nums[nums.length - 1].textContent, 10) : 1;
          var curIdx = 0;
          nums.forEach(function (n, idx) { if (n.classList.contains('giencoder-pagination-item-active')) curIdx = idx; });
          var targetIdx = curIdx;
          if (pgItem.hasAttribute('aria-label')) {
            var isPrev = pgItem.getAttribute('aria-label') === '上一页';
            targetIdx = Math.min(nums.length - 1, Math.max(0, curIdx + (isPrev ? -1 : 1)));
          } else {
            nums.forEach(function (n, idx) { if (n === pgItem) targetIdx = idx; });
          }
          nums.forEach(function (n) { n.classList.remove('giencoder-pagination-item-active'); n.removeAttribute('aria-current'); });
          nums[targetIdx].classList.add('giencoder-pagination-item-active');
          nums[targetIdx].setAttribute('aria-current', 'page');
          var prev = pg.querySelector('.rq-pg-prev');
          var next = pg.querySelector('.rq-pg-next');
          if (prev) prev.disabled = (parseInt(nums[targetIdx].textContent, 10) === 1);
          if (next) next.disabled = (parseInt(nums[targetIdx].textContent, 10) === max);
        }
      }
      var th = ev.target.closest ? ev.target.closest('.giencoder-table-th-sortable') : null;
      if (th) {
        var nextSort = th.getAttribute('data-sort') === 'asc' ? 'desc' : 'asc';
        th.setAttribute('data-sort', nextSort);
        th.setAttribute('aria-sort', nextSort === 'asc' ? 'ascending' : 'descending');
      }
    });
    var panel = wrap.querySelector('.rq-panel');
    if (panel && panel.getAttribute('data-state') === 'loading') {
      setTimeout(function () { if (panel.isConnected) panel.setAttribute('data-state', 'ready'); }, 800);
    }
  }

  /* ===== 智能助手悬浮球：按住可拖动 ===== */
  function bindFab(root) {
    var fab = root.querySelector('.kb-fab');
    if (!fab || fab._dragBound) return;
    fab._dragBound = true;
    var panel = fab.closest ? fab.closest('.kb-panel') : null;
    if (!panel) panel = fab.parentElement;
    var dragging = false, moved = false, sx = 0, sy = 0, ox = 0, oy = 0;

    /* right/bottom 定位换算成 left/top，便于自由拖动 */
    function toLeftTop() {
      if (fab.style.left) return;
      var pr = panel.getBoundingClientRect(), fr = fab.getBoundingClientRect();
      fab.style.left = (fr.left - pr.left) + 'px';
      fab.style.top = (fr.top - pr.top) + 'px';
      fab.style.right = 'auto';
      fab.style.bottom = 'auto';
    }
    function bounds() {
      return { x: Math.max(0, panel.clientWidth - fab.offsetWidth),
               y: Math.max(0, panel.clientHeight - fab.offsetHeight) };
    }
    function clamp(v, max) { return v < 0 ? 0 : (v > max ? max : v); }

    fab.addEventListener('pointerdown', function (ev) {
      if (ev.button !== 0) return;
      toLeftTop();
      dragging = true; moved = false;
      sx = ev.clientX; sy = ev.clientY;
      ox = parseFloat(fab.style.left) || 0;
      oy = parseFloat(fab.style.top) || 0;
      fab.classList.add('is-dragging');
      try { fab.setPointerCapture(ev.pointerId); } catch (e) {}
      ev.preventDefault();
    });
    fab.addEventListener('pointermove', function (ev) {
      if (!dragging) return;
      var dx = ev.clientX - sx, dy = ev.clientY - sy;
      if (!moved && Math.abs(dx) + Math.abs(dy) < 3) return;
      moved = true;
      var b = bounds();
      fab.style.left = clamp(ox + dx, b.x) + 'px';
      fab.style.top = clamp(oy + dy, b.y) + 'px';
    });
    function endDrag(ev) {
      if (!dragging) return;
      dragging = false;
      fab.classList.remove('is-dragging');
      try { fab.releasePointerCapture(ev.pointerId); } catch (e) {}
    }
    fab.addEventListener('pointerup', endDrag);
    fab.addEventListener('pointercancel', endDrag);
    /* 拖动结束后紧随的 click 不应触发悬浮球点击行为 */
    fab.addEventListener('click', function (ev) {
      if (moved) { moved = false; ev.stopImmediatePropagation(); ev.preventDefault(); }
    });
  }

  /* ===== 待介入卡片：橙色虚线持续流动 ===== */
  function bindDashedCards(root) {
    var NS = 'http://www.w3.org/2000/svg';
    Array.prototype.forEach.call(root.querySelectorAll('.kb-card.is-dashed'), function (card) {
      if (card.querySelector('.kb-card-dash')) return;
      var svg = document.createElementNS(NS, 'svg');
      svg.setAttribute('class', 'kb-card-dash');
      svg.setAttribute('aria-hidden', 'true');
      var rect = document.createElementNS(NS, 'rect');
      svg.appendChild(rect);
      card.insertBefore(svg, card.firstChild);
      function size() {
        var w = card.clientWidth, h = card.clientHeight;
        if (!w || !h) return;
        svg.setAttribute('width', w);
        svg.setAttribute('height', h);
        svg.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
        rect.setAttribute('x', '0.5');
        rect.setAttribute('y', '0.5');
        rect.setAttribute('width', String(Math.max(0, w - 1)));
        rect.setAttribute('height', String(Math.max(0, h - 1)));
        rect.setAttribute('rx', '7.5');
        rect.setAttribute('ry', '7.5');
      }
      size();
      if (window.ResizeObserver) new ResizeObserver(size).observe(card);
      else window.addEventListener('resize', size);
    });
  }

  /* ===== 顶栏：kb-radio 跟随 kb-proj-select，固定 8px 间隙 ===== */
  function bindTopbar(root) {
    var sel = root.querySelector('.kb-proj-select');
    var radio = root.querySelector('.kb-radio');
    if (!sel || !radio) return;
    var GAP = 8;
    function place() {
      var host = radio.offsetParent || sel.parentElement;
      if (!host) return;
      var hr = host.getBoundingClientRect(), sr = sel.getBoundingClientRect();
      radio.style.left = Math.round(sr.right - hr.left + GAP) + 'px';
    }
    place();
    if (window.ResizeObserver) new ResizeObserver(place).observe(sel);
    else window.addEventListener('resize', place);
  }

  function inject() {
    var main = document.querySelector('main');
    if (!main || main.querySelector('.kb-panel')) return false;
    var wrap = document.createElement('div');
    wrap.className = 'kb-wrap';
    wrap.innerHTML = KB_HTML;
    main.appendChild(wrap);
    bindComponents(wrap);
    bindFab(wrap);
    bindTopbar(wrap);
    bindDashedCards(wrap);
    bindReqPage(wrap);
    return true;
  }
  if (!inject()) {
    var mo = new MutationObserver(function () { if (inject()) mo.disconnect(); });
    mo.observe(document.body, { childList: true, subtree: true });
  }
